import { useEffect, useMemo, useRef, useState } from 'react';
import { trackEvent } from '../core/analytics';
import { BrowserImageCompressor } from '../core/imageProcessor';
import { formatBytes, validateImageFile } from '../core/metrics';
import { createBrowserRecentTaskStore } from '../core/recentTasks';
import { disclosures, imageCompressManifest } from '../core/toolManifest';
import type { CompressionOptions, ProcessingResult, RecentTask, SupportedMimeType } from '../core/types';

const defaultOptions: CompressionOptions = {
  quality: imageCompressManifest.parameters.quality.defaultValue,
  maxWidth: imageCompressManifest.parameters.maxWidth.defaultValue,
  outputType: imageCompressManifest.parameters.outputType.defaultValue
};

export function App() {
  const compressor = useMemo(() => new BrowserImageCompressor(), []);
  const recentStore = useMemo(() => createBrowserRecentTaskStore(), []);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [sourcePreview, setSourcePreview] = useState<string | null>(null);
  const [options, setOptions] = useState<CompressionOptions>(defaultOptions);
  const [result, setResult] = useState<ProcessingResult | null>(null);
  const [recentTasks, setRecentTasks] = useState<RecentTask[]>([]);
  const [progress, setProgress] = useState({ value: 0, label: '' });
  const [error, setError] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  useEffect(() => {
    trackEvent('home_view', { tool: imageCompressManifest.slug });
    setRecentTasks(recentStore.list());
  }, [recentStore]);

  useEffect(() => {
    return () => {
      if (sourcePreview) {
        URL.revokeObjectURL(sourcePreview);
      }
      if (result?.previewUrl) {
        URL.revokeObjectURL(result.previewUrl);
      }
    };
  }, [result?.previewUrl, sourcePreview]);

  function handleFile(file: File) {
    const validation = validateImageFile(file);
    if (!validation.valid) {
      setError(validation.reason ?? '图片不可用。');
      trackEvent('process_fail', { reason: validation.reason });
      return;
    }

    if (sourcePreview) {
      URL.revokeObjectURL(sourcePreview);
    }
    setSelectedFile(file);
    setSourcePreview(URL.createObjectURL(file));
    setResult(null);
    setError(null);
    trackEvent('input_ready', {
      fileSize: file.size,
      mimeType: file.type
    });
  }

  async function processFile(nextOptions = options) {
    if (!selectedFile) {
      setError('请先选择一张图片。');
      return;
    }

    setIsProcessing(true);
    setError(null);
    setProgress({ value: 0.04, label: '准备处理' });
    trackEvent('process_start', {
      quality: nextOptions.quality,
      maxWidth: nextOptions.maxWidth,
      outputType: nextOptions.outputType
    });

    try {
      const nextResult = await compressor.process(
        { file: selectedFile, options: nextOptions },
        (value, label) => setProgress({ value, label })
      );
      setResult(nextResult);
      const nextRecent = recentStore.add({
        id: nextResult.id,
        fileName: nextResult.originalFileName,
        createdAt: nextResult.createdAt,
        originalSize: nextResult.originalSize,
        outputSize: nextResult.outputSize,
        quality: nextResult.options.quality,
        maxWidth: nextResult.options.maxWidth,
        mimeType: nextResult.outputMimeType
      });
      setRecentTasks(nextRecent);
      trackEvent('process_success', {
        originalSize: nextResult.originalSize,
        outputSize: nextResult.outputSize,
        compressionRate: nextResult.compressionRate
      });
    } catch (caught) {
      const message = caught instanceof Error ? caught.message : '处理失败，请换一张图片重试。';
      setError(message);
      trackEvent('process_fail', { reason: message });
    } finally {
      setIsProcessing(false);
    }
  }

  function downloadResult() {
    if (!result) {
      return;
    }

    const link = document.createElement('a');
    link.href = result.previewUrl;
    link.download = result.outputFileName;
    link.click();
    trackEvent('export_click', {
      outputSize: result.outputSize,
      outputType: result.outputMimeType
    });
  }

  function reuseLastSettings(task: RecentTask) {
    const nextOptions: CompressionOptions = {
      quality: task.quality,
      maxWidth: task.maxWidth,
      outputType: task.mimeType
    };
    setOptions(nextOptions);
    trackEvent('reuse_click', { taskId: task.id });
  }

  return (
    <main>
      <section className="hero" aria-labelledby="hero-title">
        <div className="hero-copy">
          <p className="eyebrow">本地处理 · 无需登录 · 首版单工具</p>
          <h1 id="hero-title">图片压缩助手</h1>
          <p className="hero-text">
            把微信里临时要发送的 JPG、PNG、WebP 图片压小。图片在浏览器本地处理，不上传服务器。
          </p>
          <div className="hero-actions">
            <button
              className="primary-button"
              type="button"
              onClick={() => {
                trackEvent('cta_click', { location: 'hero' });
                fileInputRef.current?.click();
              }}
            >
              选择图片
            </button>
            <a className="secondary-button" href="#compliance">
              查看隐私说明
            </a>
          </div>
        </div>
        <div className="metric-strip" aria-label="首版验证指标">
          <Metric label="核心指标" value="完成并导出任务数" />
          <Metric label="输入" value="上传完成率" />
          <Metric label="结果" value="导出率" />
        </div>
      </section>

      <section className="workspace" aria-labelledby="workspace-title">
        <div className="section-heading">
          <p className="eyebrow">3 步任务流</p>
          <h2 id="workspace-title">上传、调参数、导出结果</h2>
        </div>

        <div className="tool-grid">
          <div
            className="upload-panel"
            onDragOver={(event) => event.preventDefault()}
            onDrop={(event) => {
              event.preventDefault();
              const file = event.dataTransfer.files[0];
              if (file) {
                handleFile(file);
              }
            }}
          >
            <input
              ref={fileInputRef}
              className="visually-hidden"
              type="file"
              accept={imageCompressManifest.supportedMimeTypes.join(',')}
              onChange={(event) => {
                const file = event.target.files?.[0];
                if (file) {
                  handleFile(file);
                }
              }}
            />
            <div className="upload-box">
              <span className="upload-mark" aria-hidden="true">
                <svg viewBox="0 0 24 24" role="img">
                  <path d="M12 4v11" />
                  <path d="m7 9 5-5 5 5" />
                  <path d="M5 20h14" />
                </svg>
              </span>
              <h3>{selectedFile ? selectedFile.name : '拖入图片或手动选择'}</h3>
              <p>
                支持 JPG、PNG、WebP，单张不超过 {formatBytes(imageCompressManifest.maxFileSizeBytes)}。
              </p>
              <button className="secondary-button compact" type="button" onClick={() => fileInputRef.current?.click()}>
                选择文件
              </button>
            </div>

            {sourcePreview && selectedFile ? (
              <div className="preview-block">
                <img src={sourcePreview} alt={`${selectedFile.name} 原图预览`} />
                <div>
                  <strong>原图</strong>
                  <span>{formatBytes(selectedFile.size)}</span>
                </div>
              </div>
            ) : null}
          </div>

          <div className="control-panel">
            <label>
              <span>压缩质量：{Math.round(options.quality * 100)}%</span>
              <input
                type="range"
                min={imageCompressManifest.parameters.quality.min}
                max={imageCompressManifest.parameters.quality.max}
                step={imageCompressManifest.parameters.quality.step}
                value={options.quality}
                onChange={(event) => setOptions({ ...options, quality: Number(event.target.value) })}
              />
            </label>

            <label>
              <span>最长边宽度：{options.maxWidth}px</span>
              <input
                type="range"
                min={imageCompressManifest.parameters.maxWidth.min}
                max={imageCompressManifest.parameters.maxWidth.max}
                step={imageCompressManifest.parameters.maxWidth.step}
                value={options.maxWidth}
                onChange={(event) => setOptions({ ...options, maxWidth: Number(event.target.value) })}
              />
            </label>

            <fieldset>
              <legend>输出格式</legend>
              <div className="segmented">
                {imageCompressManifest.parameters.outputType.options.map((type) => (
                  <button
                    key={type}
                    type="button"
                    className={options.outputType === type ? 'active' : ''}
                    onClick={() => setOptions({ ...options, outputType: type as SupportedMimeType })}
                  >
                    {formatMime(type)}
                  </button>
                ))}
              </div>
            </fieldset>

            <button className="primary-button full" type="button" disabled={!selectedFile || isProcessing} onClick={() => processFile()}>
              {isProcessing ? '处理中' : '开始压缩'}
            </button>

            {isProcessing ? (
              <div className="progress" aria-live="polite">
                <span>{progress.label}</span>
                <div>
                  <i style={{ width: `${Math.round(progress.value * 100)}%` }} />
                </div>
              </div>
            ) : null}
            {error ? <p className="error" role="alert">{error}</p> : null}
          </div>

          <ResultPanel result={result} onDownload={downloadResult} onRepeat={() => processFile()} />
        </div>
      </section>

      <section className="retention" aria-labelledby="retention-title">
        <div className="section-heading">
          <p className="eyebrow">留存触发器</p>
          <h2 id="retention-title">最近 5 次本地记录</h2>
        </div>
        <div className="recent-list">
          {recentTasks.length ? (
            recentTasks.map((task) => (
              <button className="recent-item" key={task.id} type="button" onClick={() => reuseLastSettings(task)}>
                <span>{task.fileName}</span>
                <strong>
                  {formatBytes(task.originalSize)} → {formatBytes(task.outputSize)}
                </strong>
                <small>{Math.round(task.quality * 100)}% · {task.maxWidth}px · {formatMime(task.mimeType)}</small>
              </button>
            ))
          ) : (
            <p className="empty">完成一次压缩后，这里会保存最近参数，方便下次复用。</p>
          )}
        </div>
      </section>

      <section className="compliance" id="compliance" aria-labelledby="compliance-title">
        <div className="section-heading">
          <p className="eyebrow">合规基本盘</p>
          <h2 id="compliance-title">隐私、开源披露与下一步</h2>
        </div>
        <div className="compliance-grid">
          <article>
            <h3>文件处理说明</h3>
            <p>首版所有压缩都在浏览器本地完成，不上传服务器，不做云端历史，不要求登录。</p>
          </article>
          <article>
            <h3>开源披露</h3>
            <ul>
              {disclosures.map((item) => (
                <li key={item.name}>
                  <a href={item.repository} target="_blank" rel="noreferrer">{item.name}</a> · {item.license}
                </li>
              ))}
            </ul>
          </article>
          <article>
            <h3>相邻工具</h3>
            {imageCompressManifest.relatedTools.map((tool) => (
              <button
                className="text-link"
                key={tool.slug}
                type="button"
                onClick={() => trackEvent('related_tool_click', { slug: tool.slug })}
              >
                {tool.name}：{tool.reason}
              </button>
            ))}
          </article>
        </div>
      </section>
    </main>
  );
}

function ResultPanel({
  result,
  onDownload,
  onRepeat
}: {
  result: ProcessingResult | null;
  onDownload: () => void;
  onRepeat: () => void;
}) {
  if (!result) {
    return (
      <div className="result-panel placeholder">
        <h3>结果页是留存页</h3>
        <p>压缩完成后会显示前后体积、节省比例、下载按钮和再次处理入口。</p>
      </div>
    );
  }

  return (
    <div className="result-panel">
      <div className="result-media">
        <img src={result.previewUrl} alt={`${result.outputFileName} 压缩结果预览`} />
      </div>
      <div className="result-stats">
        <Metric label="原图" value={formatBytes(result.originalSize)} />
        <Metric label="结果" value={formatBytes(result.outputSize)} />
        <Metric label="节省" value={`${result.compressionRate}%`} />
      </div>
      <p className="result-note">
        输出 {result.width} × {result.height}px · {formatMime(result.outputMimeType)}
      </p>
      <div className="result-actions">
        <button className="primary-button" type="button" onClick={onDownload}>
          下载结果
        </button>
        <button className="secondary-button" type="button" onClick={onRepeat}>
          同样设置再处理
        </button>
      </div>
    </div>
  );
}

function Metric({ label, value }: { label: string; value: string }) {
  return (
    <div className="metric">
      <span>{label}</span>
      <strong>{value}</strong>
    </div>
  );
}

function formatMime(type: string) {
  return type.replace('image/', '').toUpperCase().replace('JPEG', 'JPG');
}

