    isProcessing: false,
    error: '',
    recent: []
  },

  onLoad() {
    this.setData({
      recent: wx.getStorageSync(RECENT_KEY) || []
    });
  },

  chooseImage() {
    wx.chooseMedia({
      count: 1,
      mediaType: ['image'],
      sourceType: ['album', 'camera'],
      success: (response) => {
        const file = response.tempFiles[0];
        if (!file) return;
        if (file.size > 10 * 1024 * 1024) {
          this.setData({ error: '图片需小于 10MB，避免手机端卡顿。' });
