import { validateImageFile } from './metrics';
import { createTextResult } from './resultTypes';
import type { TextResult } from './types';

export interface OcrInput {
  file: File;
  language: string;
}

export interface OcrAdapter {
  recognize(file: File, language: string): Promise<{
    text: string;
    confidence: number;
  }>;
}

export class BrowserOcrProcessor {
  constructor(private readonly adapter: OcrAdapter = new TesseractOcrAdapter()) {}

  async process(input: OcrInput): Promise<TextResult> {
    const validation = validateImageFile(input.file);
    if (!validation.valid) {
      throw new Error(validation.reason);
    }

    const startedAt = performance.now();

    try {
      const recognized = await this.adapter.recognize(input.file, input.language);
      return createTextResult({
        toolSlug: 'photo-ocr',
        sourceFileName: input.file.name,
        text: recognized.text,
        confidence: recognized.confidence,
        durationMs: Math.round(performance.now() - startedAt)
      });
    } catch (error) {
      const detail = error instanceof Error ? error.message : 'unknown';
      throw new Error(`OCR 识别失败，请换一张更清晰的图片重试。(${detail})`);
    }
  }
}

class TesseractOcrAdapter implements OcrAdapter {
  async recognize(file: File, language: string): Promise<{ text: string; confidence: number }> {
    const { recognize } = await import('tesseract.js');
    const result = await recognize(file, language);

    return {
      text: result.data.text,
      confidence: result.data.confidence
    };
  }
}

import { PDFDocument } from 'pdf-lib';
import { createPdfResult, stripExtension } from './resultTypes';
import type { PdfResult } from './types';

interface PdfBytesInput {
  toolSlug: string;
  sourceFileName: string;
  bytes: Uint8Array;
  pageCount: number;
}

export function getPdfOutputName(sourceFileName: string): string {
  return `${stripExtension(sourceFileName) || 'document'}.pdf`;
}

export function createPdfResultFromBytes(input: PdfBytesInput): PdfResult {
  const blob = new Blob([input.bytes], { type: 'application/pdf' });
  return {
    ...createPdfResult({
      toolSlug: input.toolSlug,
      sourceFileName: input.sourceFileName,
      blob,
      pageCount: input.pageCount
    }),
    outputFileName: getPdfOutputName(input.sourceFileName)
  };
}

export async function createPdfFromImageFiles(files: File[], toolSlug = 'scan-to-pdf'): Promise<PdfResult> {
  if (!files.length) {
    throw new Error('请先选择至少一张图片。');
  }

  const pdf = await PDFDocument.create();

  for (const file of files) {
    const bytes = new Uint8Array(await file.arrayBuffer());
    const image = file.type === 'image/png' ? await pdf.embedPng(bytes) : await pdf.embedJpg(bytes);
    const page = pdf.addPage([image.width, image.height]);
    page.drawImage(image, {
      x: 0,
      y: 0,
      width: image.width,
      height: image.height
    });
  }

  return createPdfResultFromBytes({
    toolSlug,
    sourceFileName: files.length === 1 ? files[0].name : 'merged-images.pdf',
    bytes: await pdf.save(),
    pageCount: files.length
  });
}

export async function mergePdfFiles(files: File[]): Promise<PdfResult> {
  if (files.length < 2) {
    throw new Error('PDF 合并至少需要 2 个文件。');
  }

  const output = await PDFDocument.create();

  for (const file of files) {
    const source = await PDFDocument.load(await file.arrayBuffer());
    const pages = await output.copyPages(source, source.getPageIndices());
    pages.forEach((page) => output.addPage(page));
  }

  return createPdfResultFromBytes({
    toolSlug: 'pdf-tools',
    sourceFileName: 'merged.pdf',
    bytes: await output.save(),
    pageCount: output.getPageCount()
  });
}

