.task-header p {
  margin: 0;
  color: var(--muted);
  line-height: 1.6;
}

.upload-panel.embedded {
  border: 0;
  box-shadow: none;
  padding: 0;
  background: transparent;
}

.upload-box {
  min-height: 250px;
  border: 1px dashed #abc2b5;
  border-radius: 8px;
  display: grid;
  place-items: center;
