          <section className="task-panel" aria-label={activeTool?.name}>
            <div className="task-header">
              <div>
                <p className="eyebrow">{activeTool?.processingMode === 'local' ? '鏈湴澶勭悊' : '鏈湴浼樺厛 / 鍙墿浜戣兘鍔?}</p>
                <h3>{activeTool?.name}</h3>
