const RESULT_PREFIX = 'office-tools.result.';

function saveResult(payload) {
  const id = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  wx.setStorageSync(`${RESULT_PREFIX}${id}`, {
    id,
    createdAt: new Date().toISOString(),
    ...payload
  });
  return id;
}

function getResult(id) {
  if (!id) return null;
  return wx.getStorageSync(`${RESULT_PREFIX}${id}`) || null;
}

function openResult(payload) {
  const resultId = saveResult(payload);
  wx.navigateTo({ url: `/pages/result/result?resultId=${encodeURIComponent(resultId)}` });
}

module.exports = {
  RESULT_PREFIX,
  saveResult,
  getResult,
  openResult
};

const { normalizeError } = require('./errors');

function ensureCloudReady() {
  if (!wx.cloud) {
    throw { errorCode: 'CLOUD_NOT_AVAILABLE' };
  }
}

function getFileName(filePath, fallback = 'file') {
  const parts = String(filePath || '').split(/[\\/]/);
  return parts[parts.length - 1] || fallback;
}

function uploadLocalFile(filePath, directory) {
  ensureCloudReady();
  const safeName = getFileName(filePath).replace(/[^\w.-]/g, '_');
  const cloudPath = `${directory}/${Date.now()}-${Math.random().toString(36).slice(2, 8)}-${safeName}`;

  return new Promise((resolve, reject) => {
    wx.cloud.uploadFile({
      cloudPath,
      filePath,
      success: (response) => resolve(response.fileID),
      fail: (error) => reject({ ...normalizeError(error), errorCode: 'UPLOAD_FAILED' })
    });
  });
}

function callCloudFunction(name, data) {
  ensureCloudReady();
  return new Promise((resolve, reject) => {
    wx.cloud.callFunction({
      name,
      data,
      success: (response) => {
        const result = response.result || {};
        if (result.ok === false) {
          reject(normalizeError(result));
          return;
        }
        resolve(result);
      },
      fail: (error) => reject(normalizeError(error))
    });
  });
}

function downloadCloudFile(fileID) {
  ensureCloudReady();
  return new Promise((resolve, reject) => {
    wx.cloud.downloadFile({
      fileID,
      success: (response) => resolve(response.tempFilePath),
      fail: (error) => reject(normalizeError(error))
    });
  });
}

module.exports = {
  uploadLocalFile,
  callCloudFunction,
  downloadCloudFile
};

