function createMain(options = {}) {
  const db = options.db || createDatabase();
  const now = options.now || (() => new Date().toISOString());

  return async function main(event = {}) {
    const validation = validate(event);
    if (!validation.ok) {
      return validation;
    }

    const data = {
      toolSlug: event.toolSlug,
      rating: Number(event.rating),
      category: event.category,
      content: String(event.content).trim(),
      contact: event.contact || '',
      context: event.context || {},
      createdAt: now()
    };

    try {
      if (!db) {
        return fail('FEEDBACK_STORE_NOT_CONFIGURED', '反馈服务未配置，请稍后重试。');
      }
      const response = await db.collection('feedback').add({ data });
      return { ok: true, id: response._id || response.id || '' };
    } catch (error) {
      return fail('FEEDBACK_FAILED', `反馈提交失败：${error.message || 'unknown'}`);
    }
  };
}

function createDatabase() {
  try {
    const cloud = require('wx-server-sdk');
    cloud.init({ env: cloud.DYNAMIC_CURRENT_ENV });
    return cloud.database();
  } catch (error) {
    return null;
  }
}

function validate(event) {
  if (!event.toolSlug || !event.content) {
    return fail('INVALID_INPUT', '请填写反馈内容。');
  }
  const rating = Number(event.rating);
  if (!Number.isFinite(rating) || rating < 1 || rating > 5) {
    return fail('INVALID_INPUT', '评分需在 1 到 5 之间。');
  }
  return { ok: true };
}

function fail(errorCode, message) {
  return { ok: false, errorCode, message };
}

const main = createMain();

module.exports = {
  createMain,
  main
};

const { PDFDocument } = require('pdf-lib');

function createMain(options = {}) {
  const cloud = options.cloud || createCloud();
  const now = options.now || (() => Date.now());

  return async function main(event = {}) {
    const mode = event.mode;
    const fileIDs = Array.isArray(event.fileIDs) ? event.fileIDs : [];
    if (!fileIDs.length) {
      return fail('NO_FILES', '请先选择文件。');
    }
    if (mode !== 'imagesToPdf' && mode !== 'mergePdf') {
      return fail('INVALID_INPUT', 'PDF 处理模式不支持。');
    }
    if (mode === 'mergePdf' && fileIDs.length < 2) {
      return fail('INVALID_INPUT', 'PDF 合并至少需要 2 个文件。');
    }

    try {
      const pdf = await PDFDocument.create();
      if (mode === 'imagesToPdf') {
        for (const fileID of fileIDs) {
          const downloaded = await cloud.downloadFile({ fileID });
          const bytes = toUint8Array(downloaded.fileContent);
          const image = await embedImage(pdf, bytes, fileID);
          const page = pdf.addPage([image.width, image.height]);
          page.drawImage(image, { x: 0, y: 0, width: image.width, height: image.height });
        }
      } else {
        for (const fileID of fileIDs) {
          const downloaded = await cloud.downloadFile({ fileID });
          const source = await PDFDocument.load(downloaded.fileContent);
          const pages = await pdf.copyPages(source, source.getPageIndices());
          pages.forEach((page) => pdf.addPage(page));
        }
      }

      const bytes = await pdf.save();
      const outputName = sanitizeOutputName(event.outputName || `${mode}-${now()}.pdf`);
      const cloudPath = `pdf-output/${now()}-${outputName}`;
      const uploaded = await cloud.uploadFile({
        cloudPath,
        fileContent: Buffer.from(bytes)
      });

      return {
        ok: true,
        fileID: uploaded.fileID,
        outputName,
        pageCount: pdf.getPageCount(),
        fileSize: bytes.length,
        fileSizeLabel: formatBytes(bytes.length),
        expiresAt: new Date(now() + 24 * 60 * 60 * 1000).toISOString()
      };
    } catch (error) {
      return fail('PDF_FAILED', `PDF 处理失败：${error.message || 'unknown'}`);
    }
  };
}

function createCloud() {
  const cloud = require('wx-server-sdk');
  cloud.init({ env: cloud.DYNAMIC_CURRENT_ENV });
  return cloud;
}

function toUint8Array(content) {
  if (content instanceof Uint8Array) return content;
  return new Uint8Array(content);
}

async function embedImage(pdf, bytes, fileID) {
  const lower = String(fileID).toLowerCase();
  if (lower.endsWith('.png')) {
    return pdf.embedPng(bytes);
  }
  return pdf.embedJpg(bytes);
}

function sanitizeOutputName(name) {
  const safe = String(name).replace(/[^\w.-]/g, '_');
  return safe.endsWith('.pdf') ? safe : `${safe}.pdf`;
}

function formatBytes(bytes) {
  if (!bytes) return '0 B';
  const units = ['B', 'KB', 'MB'];
  const exponent = Math.min(Math.floor(Math.log(bytes) / Math.log(1024)), units.length - 1);
  const value = bytes / Math.pow(1024, exponent);
  return `${Number.isInteger(value) ? value : value.toFixed(1)} ${units[exponent]}`;
}

function fail(errorCode, message) {
  return { ok: false, errorCode, message };
}

const main = createMain();

module.exports = {
  createMain,
  main
};

function createMain(options = {}) {
  const env = options.env || process.env;
  const cloud = options.cloud || createCloud();
  const ocrProvider = options.ocrProvider || createTencentOcrProvider(env);
  const now = options.now || (() => Date.now());

  return async function main(event = {}) {
    const startedAt = now();
    const fileID = event.fileID;
    if (!fileID) {
      return fail('NO_FILES', '请先上传需要识别的图片。');
    }

    if (!env.TENCENTCLOUD_SECRET_ID || !env.TENCENTCLOUD_SECRET_KEY || !ocrProvider) {
      return fail('OCR_NOT_CONFIGURED', 'OCR 服务未配置，暂时不能识别文字。');
    }

    try {
      const downloaded = await cloud.downloadFile({ fileID });
      const recognized = await ocrProvider.recognize({
        imageBuffer: downloaded.fileContent,
        language: event.language || 'zh_en'
      });

      return {
        ok: true,
        text: recognized.text || '',
        confidence: Number(recognized.confidence || 0),
        blocks: recognized.blocks || [],
        durationMs: Math.max(0, now() - startedAt),
        provider: 'tencentcloud-ocr'
      };
    } catch (error) {
      return fail('OCR_FAILED', `OCR 识别失败：${error.message || 'unknown'}`);
    }
  };
}

function createCloud() {
  const cloud = require('wx-server-sdk');
  cloud.init({ env: cloud.DYNAMIC_CURRENT_ENV });
  return cloud;
}

function createTencentOcrProvider(env) {
  try {
    const tencentcloud = require('tencentcloud-sdk-nodejs');
    const OcrClient = tencentcloud.ocr.v20181119.Client;
    const client = new OcrClient({
      credential: {
        secretId: env.TENCENTCLOUD_SECRET_ID,
        secretKey: env.TENCENTCLOUD_SECRET_KEY
      },
      region: env.TENCENTCLOUD_OCR_REGION || 'ap-guangzhou',
      profile: {
        httpProfile: {
          endpoint: 'ocr.tencentcloudapi.com'
        }
      }
    });

    return {
      async recognize(input) {
        const response = await client.GeneralBasicOCR({
          ImageBase64: Buffer.from(input.imageBuffer).toString('base64'),
          LanguageType: input.language === 'zh_en' ? 'zh_rare' : 'auto'
        });
        const blocks = (response.TextDetections || []).map((item) => ({
          text: item.DetectedText || '',
          confidence: Number(item.Confidence || 0) / 100
        }));
        const text = blocks.map((block) => block.text).filter(Boolean).join('\n');
        const confidence = blocks.length
          ? blocks.reduce((total, block) => total + block.confidence, 0) / blocks.length
          : 0;
        return { text, confidence, blocks };
      }
    };
  } catch (error) {
    return null;
  }
}

function fail(errorCode, message) {
  return { ok: false, errorCode, message };
}

const main = createMain();

module.exports = {
  createMain,
  main
};

